const char* volvoxai_runtime_backend_policy_mode_name(VolvoxaiRuntimeBackendPolicyMode value) {
    switch (value) {
        case VOLVOXAI_RUNTIME_BACKEND_POLICY_MODE_BACKEND_POLICY_MODE_PREFER: return "BACKEND_POLICY_MODE_PREFER";
        case VOLVOXAI_RUNTIME_BACKEND_POLICY_MODE_BACKEND_POLICY_MODE_REQUIRE: return "BACKEND_POLICY_MODE_REQUIRE";
        default: return NULL;
    }
}

int volvoxai_runtime_backend_policy_mode_parse(const char* name, VolvoxaiRuntimeBackendPolicyMode* value) {
    if (!name || !value) return 0;
    if (strcmp(name, "BACKEND_POLICY_MODE_PREFER") == 0) {
        *value = VOLVOXAI_RUNTIME_BACKEND_POLICY_MODE_BACKEND_POLICY_MODE_PREFER;
        return 1;
    }
    if (strcmp(name, "BACKEND_POLICY_MODE_REQUIRE") == 0) {
        *value = VOLVOXAI_RUNTIME_BACKEND_POLICY_MODE_BACKEND_POLICY_MODE_REQUIRE;
        return 1;
    }
    return 0;
}


