static SynurangLiteStatus volvoxai_runtime_adapter_revision_merge_reader(
    VolvoxaiRuntimeAdapterRevision* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_adapter_id)) break;
                break;
            case 2:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_adapter_revision)) break;
                break;
            case 3:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_report) {
                    message->field_report =
                        (VolvoxaiRuntimeOperationReport*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_report));
                    if (!message->field_report) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_runtime_operation_report_init_with_allocator(
                        message->field_report, message->_allocator);
                }
                {
                    SynurangLiteReaderInternal value_reader;
                    sl_reader_init(&value_reader, value_data, value_len);
                    status = volvoxai_runtime_operation_report_merge_reader(
                        message->field_report, &value_reader, message_depth + 1);
                }
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

