static SynurangLiteStatus volvoxai_runtime_memory_capture_options_merge_reader(
    VolvoxaiRuntimeMemoryCaptureOptions* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = synurang_lite_bytes_assign(
                    message->_allocator,
                    &message->field_protocol,
                    value_data,
                    value_len);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 2:
                if (!sl_read_bool(
                        reader, wire_type, &message->field_include_resource_inventory)) break;
                break;
            case 3:
                if (!sl_read_bool(
                        reader, wire_type, &message->field_include_domain_attestation)) break;
                break;
            case 4:
            {
                void* appended;
                if (wire_type == 2) {
                    const uint8_t* packed_data;
                    size_t packed_len;
                    SynurangLiteReaderInternal packed;
                    if (!sl_read_slice(reader, &packed_data, &packed_len)) break;
                    sl_reader_init(&packed, packed_data, packed_len);
                    while (packed.pos < packed.len) {
                        status = sl_array_append(
                            message->_allocator,
                            (void**)&message->field_requested_envelopes.data,
                            &message->field_requested_envelopes.len,
                            &message->field_requested_envelopes.cap,
                            sizeof(*message->field_requested_envelopes.data),
                            &appended);
                        if (status != SYNURANG_LITE_OK) return status;
                        if (!sl_read_enum_raw(
                                &packed,
                                (VolvoxaiRuntimeMemoryEnvelopeKind*)appended)) break;
                    }
                    if (packed.status != SYNURANG_LITE_OK || packed.pos != packed.len) {
                        reader->status = packed.status == SYNURANG_LITE_OK
                            ? SYNURANG_LITE_MALFORMED : packed.status;
                    }
                } else {
                    status = sl_array_append(
                        message->_allocator,
                        (void**)&message->field_requested_envelopes.data,
                        &message->field_requested_envelopes.len,
                        &message->field_requested_envelopes.cap,
                        sizeof(*message->field_requested_envelopes.data),
                        &appended);
                    if (status != SYNURANG_LITE_OK) return status;
                    if (!sl_read_enum(
                            reader,
                            wire_type,
                            (VolvoxaiRuntimeMemoryEnvelopeKind*)appended)) break;
                }
                break;
            }
            case 5:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_sampling_interval_nanoseconds)) break;
                message->has_sampling_interval_nanoseconds = 1;
                break;
            case 6:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_max_periodic_snapshots)) break;
                message->has_max_periodic_snapshots = 1;
                break;
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

